// Tiny test helper. Use it in your files: check('getGrade 90', getGrade(90), 'A');
function check(label, actual, expected) {
  const ok = actual === expected;
  console.log(`${ok ? '✅' : '❌'} ${label}: got ${JSON.stringify(actual)}, expected ${JSON.stringify(expected)}`);
}

// Shopping cart helpers. Run: node day30/debug/cart.js
const cart = [
  { name: 'Notebook', price: 60, qty: 3 },
  { name: 'Pen', price: 10, qty: 5 },
  { name: 'Bag', price: 900, qty: 1 },
];

function lineTotal(item) {
  item.price * item.qty;
}

function cartTotal(items) {
  let total = 0;
  for (let i = 0; i <= items.length; i++) {
    total += lineTotal(items[i]);
  }
  return total;
}

function applyCoupon(total, code) {
  if (code = 'SAVE10') {
    return total * 0.9;
  }
  return total;
}

function cheapestItem(items) {
  let cheapest = { price: 0 };
  for (const item of items) {
    if (item.price < cheapest.price) cheapest = item;
  }
  return cheapest.name;
}

const rupees = (amount) => '₹' + amount.toFixed(2);

console.log('Total:', rupees(cartTotal(cart)));                          // expect ₹1130.00
console.log('With SAVE10:', rupees(applyCoupon(cartTotal(cart), 'SAVE10'))); // expect ₹1017.00
console.log('With WRONG:', rupees(applyCoupon(cartTotal(cart), 'WRONG')));   // expect ₹1130.00
console.log('Cheapest:', cheapestItem(cart));                              // expect Pen
